"""Offline import of verified EXPC-WLK model directories."""
import ctypes
from ctypes import wintypes
import os
from pathlib import Path
import shutil
import tempfile

from . import model_store


MODEL_IDS = ("small", "large-v3-turbo")


class ModelImportError(RuntimeError):
    pass


class BROWSEINFOW(ctypes.Structure):
    _fields_ = [
        ("hwndOwner", wintypes.HWND),
        ("pidlRoot", ctypes.c_void_p),
        ("pszDisplayName", wintypes.LPWSTR),
        ("lpszTitle", wintypes.LPCWSTR),
        ("ulFlags", wintypes.UINT),
        ("lpfn", ctypes.c_void_p),
        ("lParam", wintypes.LPARAM),
        ("iImage", ctypes.c_int),
    ]


def choose_folder(title):
    """Open the native Windows folder picker without an external GUI toolkit."""
    shell32 = ctypes.windll.shell32
    ole32 = ctypes.windll.ole32
    shell32.SHBrowseForFolderW.restype = ctypes.c_void_p
    shell32.SHGetPathFromIDListW.argtypes = [ctypes.c_void_p, wintypes.LPWSTR]
    shell32.SHGetPathFromIDListW.restype = wintypes.BOOL
    ole32.CoTaskMemFree.argtypes = [ctypes.c_void_p]
    display = ctypes.create_unicode_buffer(260)
    browse = BROWSEINFOW()
    browse.pszDisplayName = display
    browse.lpszTitle = title
    browse.ulFlags = 0x0001 | 0x0040  # filesystem directories, modern dialog
    ole32.CoInitialize(None)
    try:
        pidl = shell32.SHBrowseForFolderW(ctypes.byref(browse))
        if not pidl:
            return None
        try:
            path = ctypes.create_unicode_buffer(32768)
            if not shell32.SHGetPathFromIDListW(pidl, path):
                raise ModelImportError("The selected folder is not a filesystem directory")
            return Path(path.value)
        finally:
            ole32.CoTaskMemFree(pidl)
    finally:
        ole32.CoUninitialize()


def _candidate_directories(selected, model_id):
    selected = Path(selected).resolve()
    candidates = [
        selected,
        selected / model_id,
        selected / "models" / model_id,
        selected / "Models" / model_id,
        selected / "WhisperKey" / "models" / model_id,
        selected / "EXPC-WLK" / "Models" / model_id,
    ]
    unique = []
    for candidate in candidates:
        if candidate not in unique:
            unique.append(candidate)
    return unique


def inspect_source(metadata_root, selected):
    """Find pinned model snapshots below a selected directory."""
    found = []
    incomplete = []
    for model_id in MODEL_IDS:
        manifest = model_store.manifest_for(metadata_root, model_id)
        for candidate in _candidate_directories(selected, model_id):
            present = [item for item in manifest["files"] if (candidate / item["name"]).is_file()]
            if not present:
                continue
            missing = [item["name"] for item in manifest["files"]
                       if not (candidate / item["name"]).is_file()]
            if missing:
                incomplete.append({"model": model_id, "path": candidate, "missing": missing})
                continue
            if all(model_store.valid_file(candidate / item["name"], item)
                   for item in manifest["files"]):
                found.append({"model": model_id, "path": candidate})
            else:
                incomplete.append({"model": model_id, "path": candidate, "missing": []})
            break
    return {"valid": found, "invalid": incomplete}


def import_model(metadata_root, model_root, model_id, source):
    """Copy a verified snapshot atomically and register it; never alter source."""
    metadata_root = Path(metadata_root).resolve()
    models = Path(model_root).resolve()
    source = Path(source).resolve()
    manifest = model_store.manifest_for(metadata_root, model_id)
    if model_id not in MODEL_IDS:
        raise ModelImportError("Unsupported model")
    missing = [item["name"] for item in manifest["files"]
               if not (source / item["name"]).is_file()]
    if missing:
        raise ModelImportError("Missing model files: " + ", ".join(missing))
    if not all(model_store.valid_file(source / item["name"], item)
               for item in manifest["files"]):
        raise ModelImportError("Model SHA-256 verification failed")

    models.mkdir(parents=True, exist_ok=True)
    target = (models / manifest["directory"]).resolve()
    if target.parent != models:
        raise ModelImportError("Invalid model destination")
    if source == target:
        result = model_store.verify_local_model(
            metadata_root, model_id, model_root=models)
        if result["status"] != "valid":
            raise ModelImportError("Model registration failed")
        return {"model": model_id, "path": target, "copied": False,
                "adopted": result["adopted"]}

    staging = Path(tempfile.mkdtemp(prefix=".import-" + model_id + "-", dir=models))
    previous = None
    swapped = False
    try:
        for item in manifest["files"]:
            shutil.copy2(source / item["name"], staging / item["name"])
        if not all(model_store.valid_file(staging / item["name"], item)
                   for item in manifest["files"]):
            raise ModelImportError("Copied model failed SHA-256 verification")
        if target.exists():
            previous = Path(tempfile.mkdtemp(prefix=".previous-" + model_id + "-", dir=models))
            previous.rmdir()
            os.replace(target, previous)
        try:
            os.replace(staging, target)
            swapped = True
        except Exception:
            if previous is not None and previous.exists() and not target.exists():
                os.replace(previous, target)
            raise
        result = model_store.verify_local_model(
            metadata_root, model_id, model_root=models)
        if result["status"] != "valid":
            raise ModelImportError("Imported model registration failed")
        if previous is not None:
            shutil.rmtree(previous)
            previous = None
        return {"model": model_id, "path": target, "copied": True,
                "adopted": result["adopted"]}
    except Exception:
        if previous is not None and previous.exists():
            if target.exists():
                shutil.rmtree(target)
            os.replace(previous, target)
            previous = None
        elif swapped and target.exists() and source != target:
            shutil.rmtree(target)
        raise
    finally:
        if staging.exists():
            shutil.rmtree(staging)
        if previous is not None and previous.exists() and not target.exists():
            os.replace(previous, target)


def import_selected(metadata_root, model_root, selected, preferred_model=None, chooser=None,
                    require_preferred=False):
    inspection = inspect_source(metadata_root, selected)
    valid = inspection["valid"]
    if not valid:
        if inspection["invalid"]:
            broken = inspection["invalid"][0]
            detail = ("missing " + ", ".join(broken["missing"])) if broken["missing"] else "SHA-256 mismatch"
            raise ModelImportError(f"Invalid {broken['model']} model: {detail}")
        raise ModelImportError("No supported EXPC-WLK model directory was found")
    selected_model = next((item for item in valid if item["model"] == preferred_model), None)
    if preferred_model and selected_model is None and require_preferred:
        raise ModelImportError(f"The selected folder does not contain a valid {preferred_model} model")
    if selected_model is None and len(valid) == 1:
        selected_model = valid[0]
    if selected_model is None:
        if chooser is None:
            raise ModelImportError("The selected folder contains more than one model")
        selected_model = chooser(valid)
        if selected_model is None:
            raise ModelImportError("Model import cancelled")
    return import_model(metadata_root, model_root, selected_model["model"], selected_model["path"])
